// SetDB changes the database executor of the record without touching its values — e.g. to
// run a Modify (with its rename cascade) inside a transaction.
func (t *DepreciationBook) SetDB(db database.Executor) {
	t.db = db
}

// renameReferences carries a renamed key over to every field of another table that refers
// to it (Rename). References from company tables are updated in this company — in
// every company when this table is global. Runs on the record's executor, so inside the
// caller's transaction.
func (t *DepreciationBook) renameReferences(field string, oldValue, newValue interface{}) error {
	type reference struct {
		table      string
		global     bool
		column     string
		condColumn string // a conditional relation: only rows whose condColumn = condValue
		condValue  int
	}
	references := map[string][]reference{
		"code": {{"FA_Depreciation_Book", false, "depreciation_book_code", "", 0}, {"FA_Journal_Line", false, "depreciation_book_code", "", 0}, {"FA_Journal_Line", false, "duplicate_in_depreciation_book", "", 0}, {"FA_Journal_Setup", false, "depreciation_book_code", "", 0}, {"FA_Posting_Type_Setup", false, "depreciation_book_code", "", 0}, {"FA_Reclass_Journal_Line", false, "depreciation_book_code", "", 0}, {"FA_Setup", false, "default_depr_book", "", 0}, {"FA_Setup", false, "insurance_depr_book", "", 0}, {"FA_Ledger_Entry", false, "depreciation_book_code", "", 0}, {"Gen_Journal_Line", false, "depreciation_book_code", "", 0}, {"Gen_Journal_Line", false, "duplicate_in_depreciation_book", "", 0}, {"Maintenance_Ledger_Entry", false, "depreciation_book_code", "", 0}, {"Purch_Cr_Memo_Line", false, "depreciation_book_code", "", 0}, {"Purch_Cr_Memo_Line", false, "duplicate_in_depreciation_book", "", 0}, {"Purch_Inv_Line", false, "depreciation_book_code", "", 0}, {"Purch_Inv_Line", false, "duplicate_in_depreciation_book", "", 0}, {"Purchase_Line", false, "depreciation_book_code", "", 0}, {"Purchase_Line", false, "duplicate_in_depreciation_book", "", 0}},
	}
	companies := []string{t.company}
	for _, ref := range references[field] {
		tables := []string{ref.table}
		if !ref.global {
			tables = tables[:0]
			for _, c := range companies {
				tables = append(tables, c+"$"+ref.table)
			}
		}
		for _, tbl := range tables {
			stmt := fmt.Sprintf(`UPDATE "%s" SET %s = ? WHERE %s = ?`, tbl, ref.column, ref.column)
			args := []interface{}{newValue, oldValue}
			if ref.condColumn != "" {
				stmt += fmt.Sprintf(" AND %s = ?", ref.condColumn)
				args = append(args, ref.condValue)
			}
			query := t.convertPlaceholders(stmt, len(args))
			if _, err := t.db.Exec(query, args...); err != nil {
				return fmt.Errorf("%s.%s: %w", tbl, ref.column, err)
			}
		}
	}
	return nil
}

